#!/usr/bin/env python3
# BIP-173 bech32 (not bech32m) encoder/decoder, as used by age.
CHARSET = "qpzry9x8gf2tvdw0s3jn54khce6mua7l"
GEN = [0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3]

def polymod(values):
    chk = 1
    for v in values:
        b = chk >> 25
        chk = ((chk & 0x1ffffff) << 5) ^ v
        for i in range(5):
            chk ^= GEN[i] if ((b >> i) & 1) else 0
    return chk

def hrp_expand(hrp):
    return [ord(x) >> 5 for x in hrp] + [0] + [ord(x) & 31 for x in hrp]

def create_checksum(hrp, data):
    values = hrp_expand(hrp) + data
    pm = polymod(values + [0,0,0,0,0,0]) ^ 1
    return [(pm >> 5 * (5 - i)) & 31 for i in range(6)]

def convertbits(data, frombits, tobits, pad=True):
    acc = 0; bits = 0; ret = []
    maxv = (1 << tobits) - 1
    max_acc = (1 << (frombits + tobits - 1)) - 1
    for value in data:
        acc = ((acc << frombits) | value) & max_acc
        bits += frombits
        while bits >= tobits:
            bits -= tobits
            ret.append((acc >> bits) & maxv)
    if pad:
        if bits:
            ret.append((acc << (tobits - bits)) & maxv)
    elif bits >= frombits or ((acc << (tobits - bits)) & maxv):
        return None
    return ret

def encode(hrp, data_bytes):
    data = convertbits(list(data_bytes), 8, 5)
    combined = data + create_checksum(hrp, data)
    return hrp + '1' + ''.join([CHARSET[d] for d in combined])

def decode(bech):
    lo = bech.lower()
    pos = lo.rfind('1')
    hrp = lo[:pos]
    data = [CHARSET.find(c) for c in lo[pos+1:]]
    if polymod(hrp_expand(hrp) + data) != 1:
        raise ValueError("bad checksum for %r" % bech)
    return hrp, bytes(convertbits(data[:-6], 5, 8, False))

if __name__ == "__main__":
    import sys, binascii
    mode = sys.argv[1]
    if mode == "enc":
        hrp = sys.argv[2]
        raw = binascii.unhexlify(sys.argv[3]) if len(sys.argv) > 3 else b""
        out = encode(hrp, raw)
        # age uppercases identities (hrp starting with AGE-)
        print(out.upper() if hrp.upper().startswith("AGE-") else out)
    else:
        h, d = decode(sys.argv[2])
        print(h, binascii.hexlify(d).decode())
