#!/usr/bin/env python3
import os, sys, base64, time

LOG = os.environ.get("TP_LOG", "/tmp/w/plug/log.txt")
MODE = os.environ.get("TP_MODE", "exit0")

def log(s):
    with open(LOG, "a") as f:
        f.write(s)
        f.flush()

log("=== INVOCATION pid=%d ===\n" % os.getpid())
log("ARGV: %r\n" % (sys.argv,))
log("CWD: %r\n" % os.getcwd())
for k in sorted(os.environ):
    if k.startswith("AGE") or k.startswith("TP_") or k in ("PATH",):
        log("ENV %s=%s\n" % (k, os.environ[k]))
log("ISATTY stdin=%s stdout=%s stderr=%s\n" % (sys.stdin.isatty(), sys.stdout.isatty(), sys.stderr.isatty()))
log("--- STDIN RAW ---\n")

out = sys.stdout.buffer

def send(s):
    log("<<< %r\n" % s)
    out.write(s.encode())
    out.flush()

def rl():
    b = sys.stdin.buffer.readline()
    log(">>> %r\n" % b)
    return b

def read_stanza():
    """Returns (args_list, body_bytes) or None on EOF."""
    while True:
        line = rl()
        if not line:
            return None
        s = line.rstrip(b"\r\n").decode("utf-8", "replace")
        if s.startswith("-> "):
            args = s[3:].split(" ")
            break
        if s.startswith("->"):
            args = s[2:].split(" ")
            break
        # ignore unexpected
        log("!!! non-stanza line ignored\n")
    body = b""
    while True:
        bl = rl()
        if not bl:
            break
        t = bl.rstrip(b"\r\n")
        body += t
        if len(t) < 64:
            break
    try:
        dec = base64.b64decode(body + b"=" * (-len(body) % 4))
    except Exception as e:
        dec = b"<b64err %s>" % str(e).encode()
    log("### STANZA args=%r bodyb64=%r bodyraw=%r\n" % (args, body.decode(), dec))
    return (args, dec)

def b64(b):
    return base64.b64encode(b).decode().rstrip("=")

def wrap(s, w=64):
    if s == "":
        return [""]
    return [s[i:i+w] for i in range(0, len(s), w)]

def send_stanza(args, body=b"", width=64, nofinal=False):
    send("-> " + " ".join(args) + "\n")
    lines = wrap(b64(body), width)
    # standard: if last line is exactly width long, add empty line
    if not nofinal and len(lines[-1]) == width:
        lines.append("")
    for l in lines:
        send(l + "\n")

stanzas = []
while True:
    st = read_stanza()
    if st is None:
        log("--- EOF on stdin ---\n")
        break
    stanzas.append(st)
    if st[0][0] == "done":
        break

log("--- read %d stanzas, MODE=%s ---\n" % (len(stanzas), MODE))

# ------- response modes -------
if MODE == "exit0":
    pass
elif MODE == "exit7":
    log("EXITING 7\n"); sys.exit(7)
elif MODE == "garbage":
    send("this is not a stanza at all\nblah blah\n")
elif MODE == "nostanza":
    send_stanza(["done"])
elif MODE == "error":
    send_stanza(["error", "internal"], b"something went terribly wrong")
    send_stanza(["done"])
elif MODE == "custom":
    script = os.environ.get("TP_SCRIPT", "")
    exec(script)
else:
    log("UNKNOWN MODE\n")

log("=== END pid=%d rc=0 ===\n" % os.getpid())
